function abortedError(requestId?: string, partialText?: string): InferenceError {
  return new InferenceError("aborted", "operator", "Inference request aborted by operator", { requestId, partialText, failoverEligible: false });
}

/** Walk `err.cause` (and AggregateError members): fetch reports only "fetch failed"/"terminated" at the top. */
export function transportCauseChain(err: any): TransportCause[] {
  const out: TransportCause[] = [];
  const seen = new Set<unknown>();
  const visit = (e: any): void => {
    if (!e || typeof e !== "object" || seen.has(e) || out.length >= 8) return;
    seen.add(e);
    const c: TransportCause = {};
    if (typeof e.name === "string") c.name = e.name;
    if (typeof e.code === "string") c.code = e.code;
    if (typeof e.errno === "number") c.errno = e.errno;
    if (typeof e.syscall === "string") c.syscall = e.syscall;
    if (typeof e.address === "string") c.address = e.address;
    if (typeof e.port === "number") c.port = e.port;
    if (typeof e.socket?.bytesWritten === "number") c.bytesWritten = e.socket.bytesWritten;
    if (typeof e.socket?.bytesRead === "number") c.bytesRead = e.socket.bytesRead;
    if (typeof e.message === "string" && e.message) c.message = redactSecrets(e.message);
    out.push(c);
    if (Array.isArray(e.errors)) for (const sub of e.errors) visit(sub);
    visit(e.cause);
  };
  visit(err?.cause);
  return out;
}

function formatCause(chain: TransportCause[]): string {
  if (!chain.length) return "";
  return ` (cause: ${chain.map((c) => [c.code, c.message].filter(Boolean).join(": ") || c.name).join(" <- ")})`;
}

/** Classify a fetch/read rejection. `operatorSignal` distinguishes operator abort from the request timeout. */
function classifyTransportError(err: any, operatorSignal: AbortSignal | undefined, requestId: string, phase: "connect" | "stream", partialText = ""): InferenceError {
  if (err instanceof InferenceError) return err;
  if (operatorSignal?.aborted) return abortedError(requestId, partialText);
  const transportCause = transportCauseChain(err);
  const timedOut = err?.name === "TimeoutError";
  const classification = classifyTransportFailure(transportCause, phase, timedOut);
  public getProviderRecovery(): ProviderRecoveryRecord | null {
    return this.activeProviderRecovery;
  }

  /**
   * 3 s startup reachability check (`GET /models`, REQ-TUI-105). Returns an actionable warning naming the endpoint,
   * cause and fix (`nexus doctor`, `~/.config/nexus/config.env`, `/connect`) when unreachable or rejected; undefined when ok.
   */
  public async probeStartupEndpoint(signal?: AbortSignal): Promise<string | undefined> {
    const problem = await this.probeEndpointProblem(signal);
    return problem ? startupProblemWarning(problem) : undefined;
  }

  /** The same probe, structured: what is wrong (unreachable, credentials rejected) and the raw cause; undefined when usable. */
  public async probeEndpointProblem(signal?: AbortSignal, timeoutMs = 3_000): Promise<StartupEndpointProblem | undefined> {
    if (typeof this.client.probeAvailability !== "function") return undefined;
    // After a resume the hosts probe right after restoring: inside the provider's window nothing is sent. The
    // resumed turn waits it out and re-probes through live recovery, so no warning is lost.
    if (this.isProviderWindowOpen()) return undefined;
    try {
      const probe = await this.client.probeAvailability(signal, { timeoutMs });
      if (probe.available && probe.httpStatus !== undefined && probe.httpStatus >= 200 && probe.httpStatus < 300) {
        this.client.markSucceeded?.(this.client.endpoint);
      }
      return startupEndpointProblem(this.client.endpoint, probe);
    } catch {
      return undefined;
    }
  }

  public setProviderRecoveryHooks(hooks: Pick<RecoveryHooks<unknown>, "onFailure" | "shouldYield"> | undefined): void {
    this.providerRecoveryHooks = hooks;
  }

  private onProviderRecoveryState(
    record: ProviderRecoveryRecord,
   * The one way a prompt, a steer that starts a turn and a follow-up start a turn. When start-up found nothing answering,
   * it waits for that probe, asks again (the operator may have connected a provider or started a server since) and
   * refuses with the reason rather than entering a retry loop. A cancelled probe says nothing about the provider: the
   * gate stays and the turn does not run.
   */
  private async gatedTurn(
    id: string,
    text: string | any[],
    signal: AbortSignal,
    hooks: { admitted?: () => void; refused: (message: string) => void },
    turnArgs?: { title?: string; checkpoint?: string; step?: boolean },
  ): Promise<void> {
    // Cancelled while the gate was checking: the message is reported back (never silently dropped), not run.
    const cancelled = "Cancelled before it was sent.";
    await this.startupProbe;
    // With no known problem a cancel is the turn's own business (it reports INTERRUPTED); only the gate reports it here.
    if (this.providerProblem) {
      const problem = await this.app.getAgent().probeEndpointProblem(signal);
      if (signal.aborted) return hooks.refused(cancelled);
      this.providerProblem = problem?.blocking ? problem : undefined;
      if (this.providerProblem) {
        hooks.refused(noProviderRefusal(this.providerProblem));
        return;
      }
    }
    hooks.admitted?.();
